// ---------- GEGEVENS VOOR DEXXTER (menu) ----------
// Toont alles wat Alessia nodig heeft om de verkoopfactuur in Dexxter te maken (klant + factuur + artikel).
function dexxterGegevens() {
  var ui = SpreadsheetApp.getUi(), sh = sheet(), r = sh.getActiveRange().getRow();
  if (r < 2) { ui.alert('Selecteer eerst een rij met een deelnemer.'); return; }
  var v = sh.getRange(r, 1, 1, KOL.length).getValues()[0];
  function g(k) { var x = v[C[k] - 1]; return x === '' || x == null ? '' : String(x); }
  var b = bedragen(g('Tarief')), nl = function (n) { return Number(n).toFixed(2).replace('.', ','); };
  var bedrijf = g('Factuur');
  var straat = g('Straat'), huisnr = g('Huisnr'), bus = g('Bus'), pc = g('Postcode'), gem = g('Gemeente');
  if (!straat && g('Adres')) straat = g('Adres') + '  (oude inschrijving: splits zelf straat/nr/postcode)';
  var vandaag = new Date(), verval = new Date(vandaag.getTime() + 14 * 864e5);
  function d2(d) { return Utilities.formatDate(d, Session.getScriptTimeZone(), 'dd/MM/yyyy'); }
  var blokken = [
    ['1 · Klant toevoegen', [
      ['Wie is je klant?', bedrijf ? 'Belgisch bedrijf (zie opmerking)' : 'Particulier'],
      ['Land', 'België'],
      [bedrijf ? 'Bedrijfsnaam' : 'Naam', bedrijf || (g('Voornaam') + ' ' + g('Achternaam'))],
      ['E-mail', g('E-mail')], ['Telefoon', g('Telefoon')],
      ['Straatnaam', straat], ['Huisnr', huisnr], ['Busnr', bus], ['Postcode', pc], ['Gemeente', gem],
      ['Opmerkingen', bedrijf ? 'Deelnemer: ' + g('Voornaam') + ' ' + g('Achternaam') + ' · gegevens bedrijf zoals ingevuld: ' + bedrijf : 'Teacher Training ' + g('Referentie')]]],
    ['2 · Factuurgegevens', [
      ['Factuurdatum', d2(vandaag) + ' (of datum ontvangst betaling)'], ['Vervaldatum', d2(verval)],
      ['Factuurnummer', 'laat Dexxter invullen (volgend nummer)'], ['Referentie', g('Referentie') + ' ' + g('Voornaam') + ' ' + g('Achternaam')]]],
    ['3 · Artikel', [
      ['Naam', 'Reformer Teacher Training ' + CFG.editie + ' - loulou studio (' + CFG.data + ')'],
      ['Prijs excl. btw', nl(b.excl)], ['Aantal', '1'], ['Btw', '21%'],
      ['Totaal excl. btw', '€ ' + nl(b.excl)], ['Totaal btw', '€ ' + nl(b.btw)], ['Totaal incl. btw', '€ ' + nl(b.incl)]]],
    ['Betalingen', [
      ['Voorschot (50%)', '€ ' + nl(b.voorschot) + (g('Voorschot gevraagd') ? ' · gevraagd' : '')],
      ['Saldo (50%)', '€ ' + nl(b.saldo) + (g('Saldo gevraagd') ? ' · gevraagd' : '')], ['Status in sheet', g('Status')]]]
  ];
  var html = '<div style="font-family:Arial,sans-serif;font-size:13px;color:#141110">' +
    '<p style="margin:0 0 10px;color:#4A423D">Neem dit over in Dexxter. Klik in een vak en kopieer (Ctrl+C).</p>';
  blokken.forEach(function (bl) {
    html += '<div style="margin:14px 0 6px;font-size:11px;letter-spacing:2px;color:#59010E;text-transform:uppercase"><b>' + bl[0] + '</b></div><table style="width:100%;border-collapse:collapse">';
    bl[1].forEach(function (kv) {
      html += '<tr><td style="padding:5px 8px 5px 0;width:34%;color:#8E705B;border-bottom:1px solid #E4DBCE;vertical-align:top">' + esc(kv[0]) + '</td>' +
        '<td style="padding:3px 0;border-bottom:1px solid #E4DBCE"><input readonly onclick="this.select()" value="' + esc(kv[1]).replace(/"/g, '&quot;') + '" style="width:100%;border:0;font:inherit;padding:2px 0;background:transparent"></td></tr>';
    });
    html += '</table>';
  });
  html += '<p style="margin-top:14px;font-size:11px;color:#8E705B">Eén factuur voor het volledige bedrag, net zoals bij de vorige editie. Dexxter maakt een factuur pas definitief als het adres volledig is.</p></div>';
  ui.showModalDialog(HtmlService.createHtmlOutput(html).setWidth(560).setHeight(640), 'Gegevens voor Dexxter · ' + g('Voornaam') + ' ' + g('Achternaam'));
}
